// 每个record字段序必须恰好是当前schema字段全集，不能借原序藏入权源或余额字段。
Status shape(const FieldOrder& order,std::initializer_list<StableId> expected){if(order.empty())return common_success();std::set<StableId> keys(expected);if(keys.size()!=order.size())return common_failure("InvalidNavalBattleFieldOrder");for(const auto& k:order)if(keys.erase(k)!=1)return common_failure("InvalidNavalBattleFieldOrder",k);return common_success();}
// The original JSON field writer is also the borrowed no-tree writer.
Status emit_value(ProjectionWriter& w,const StableId& key,const StableId& x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,Integer x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,bool x){return w.field(key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,const Owner& x){return emit_common_owner(w,key,x);}
Status emit_value(ProjectionWriter& w,const StableId& key,const PointI& x){const std::array<Integer,2> point{x.x,x.y};return w.sequence(key,point,[](auto& c,Integer v){return c.field("",v);});}
Status emit_value(ProjectionWriter& w,const StableId& key,const WildernessLocation& x){return w.object(key,[&](auto& c){return emit_common_wilderness_location_fields(c,x);});}
Status emit_value(ProjectionWriter& w,const StableId& key,const HexPoint& x){const std::array<Integer,2> point{x.q,x.r};return w.sequence(key,point,[](auto& c,Integer v){return c.field("",v);});}
Status emit_value(ProjectionWriter& w,const StableId& key,const BattleUnit& x){return w.object(key,[&](auto& c){return battle_codec::emit_fields(c,x);});}
Status emit_value(ProjectionWriter& w,const StableId& key,const MilitaryMotionSource& x){return w.object(key,[&](auto& c){return battle_codec::emit_fields(c,x);});}
Status emit_value(ProjectionWriter&,const StableId&,const NavalTacticalOrders&);
