template<class T>Status emit_value(ProjectionWriter& w,const StableId& key,const std::vector<T>& rows){return w.sequence(key,rows,[](auto& c,const auto& row){return emit_value(c,"",row);});}
Status emit_value(ProjectionWriter& w,const StableId& key,const NavalTacticalOrders& rows){return w.object(key,[&](auto& c){for(const auto& row:rows)emit_value(c,row.first,row.second);return c.status();});}
template<class T>V projected_value(const T& value){V out;BoundaryProjectionWriter sink(out);auto checked=emit_value(sink,"",value);if(checked.ok)checked=sink.finish();if(!checked.ok)boundary::fail(checked.error.original.code,checked.error.original.path);return out;}

V enc(const StableId& x){return V{x};}V enc(Integer x){return V{x};}V enc(bool x){return V{x};}
void dec(const V& v,StableId& x,const StableId& p){x=boundary::string(v,p);}void dec(const V& v,Integer& x,const StableId& p){x=boundary::integer(v,p);}void dec(const V& v,bool& x,const StableId& p){x=boundary::boolean(v,p);}
Status walk(CodecVisitor& c,StableId& x){return c.field("value",x);}Status walk(CodecVisitor& c,Integer& x){return c.field("value",x);}Status walk(CodecVisitor& c,bool& x){return c.field("value",x);}
// 世界锚点坚持原WildernessLocation，不接受局部战场格或其它位置种类冒充。
V enc(const WildernessLocation& x){return boundary::encode_location(Location{x});}
void dec(const V& v,WildernessLocation& x,const StableId& p){auto loc=boundary::decode_location(v,p);const auto* wild=std::get_if<WildernessLocation>(&loc);if(!wild)boundary::fail("NavalWorldAnchorRequired",p);x=*wild;}
Status walk(CodecVisitor& c,WildernessLocation& x){Location loc=x;auto result=common_checkpoint::location(c,loc);if(!result.ok)return result;const auto* wild=std::get_if<WildernessLocation>(&loc);if(!wild)return c.reject("NavalWorldAnchorRequired");x=*wild;return c.status();}
V enc(const Owner& x){return boundary::encode_owner(x);}void dec(const V& v,Owner& x,const StableId& p){x=boundary::decode_owner(v,p);}Status walk(CodecVisitor& c,Owner& x){return common_checkpoint::owner(c,x);}
// 原世界整数点逐位保留，不经binary64截断。
V enc(const PointI& x){return V{A{V{x.x},V{x.y}}};}void dec(const V& v,PointI& x,const StableId& p){const auto& a=boundary::array(v,p);if(a.size()!=2)boundary::fail("InvalidNavalWorldPoint",p);x={boundary::integer(a[0],p),boundary::integer(a[1],p)};}Status walk(CodecVisitor& c,PointI& x){c.field("x",x.x);return c.field("y",x.y);}
V enc(const HexPoint& x){return V{A{V{x.q},V{x.r}}};}void dec(const V& v,HexPoint& x,const StableId& p){const auto& a=boundary::array(v,p);if(a.size()!=2)boundary::fail("InvalidHexDestination",p);x={boundary::integer(a[0],p),boundary::integer(a[1],p)};}Status walk(CodecVisitor& c,HexPoint& x){c.field("q",x.q);return c.field("r",x.r);}
V enc(const BattleUnit& x){return battle_codec::encode(x);}void dec(const V& v,BattleUnit& x,const StableId& p){battle_codec::decode(v,x,p);}Status walk(CodecVisitor& c,BattleUnit& x){return battle_codec::visit(c,x);}
V enc(const MilitaryMotionSource& x){return battle_codec::encode(x);}void dec(const V& v,MilitaryMotionSource& x,const StableId& p){battle_codec::decode(v,x,p);}Status walk(CodecVisitor& c,MilitaryMotionSource& x){return battle_codec::visit(c,x);}
