// 集合维持原顺序；有界visitor负责拒超大长度，完整World再核跨事实来源。
template<class T>V enc(const std::vector<T>& rows){A out;for(const auto& r:rows)out.push_back(enc(r));return V{std::move(out)};}
template<class T>void dec(const V& v,std::vector<T>& rows,const StableId& p){rows.clear();for(const auto& item:boundary::array(v,p)){T r;dec(item,r,p+"/"+std::to_string(rows.size()));rows.push_back(std::move(r));}}
template<class T>Status walk(CodecVisitor& c,std::vector<T>& rows){return c.sequence("rows",rows,[](auto& v,auto& r){return walk(v,r);});}
V enc(const NavalTacticalOrders& rows){D out;for(const auto& row:rows)out.emplace_back(row.first,enc(row.second));return V{std::move(out)};}
void dec(const V& v,NavalTacticalOrders& rows,const StableId& p){rows.clear();for(const auto& row:boundary::object(v,p)){NavalTacticalOrder value;dec(row.second,value,p+"/"+row.first);rows.emplace_back(row.first,std::move(value));}}
Status walk(CodecVisitor& c,NavalTacticalOrders& rows){return c.sequence("orders",rows,[](auto& v,auto& r){v.field("unit_id",r.first);return walk(v,r.second);});}
// NavalBattleBinding严格保存固定字段及原序，不推测缺省事实。
Status emit_record_fields(ProjectionWriter& w,const NavalBattleBinding& r){auto checked=shape(r.field_order,{"vessel_id","unit_id","fleet_id"});if(!checked.ok)return checked;emit_value(w,"vessel_id",r.vessel_id);emit_value(w,"unit_id",r.unit_id);emit_value(w,"fleet_id",r.fleet_id);w.order_fields(r.field_order);return w.status();}
V enc(const NavalBattleBinding& r){return projected_value(r);}
void dec(const V& v,NavalBattleBinding& r,const StableId& p){boundary::fields(v,{"vessel_id","unit_id","fleet_id"},{},p);r.field_order=boundary::order(v);dec(boundary::field(v,"vessel_id",p),r.vessel_id,p+"/vessel_id");dec(boundary::field(v,"unit_id",p),r.unit_id,p+"/unit_id");dec(boundary::field(v,"fleet_id",p),r.fleet_id,p+"/fleet_id");}
Status walk(CodecVisitor& c,NavalBattleBinding& r){c.object("vessel_id",[&](auto& v){return walk(v,r.vessel_id);});c.object("unit_id",[&](auto& v){return walk(v,r.unit_id);});c.object("fleet_id",[&](auto& v){return walk(v,r.fleet_id);});walk(c,r.field_order);if(!c.status().ok)return c.status();auto checked=shape(r.field_order,{"vessel_id","unit_id","fleet_id"});return checked.ok?c.status():c.reject(checked.error.original.code,checked.error.original.path);}
